+              </div>
+              <h2 id="dialog-title">Delete this image?</h2>
+              <p class="muted" id="dialog-description">
+                This will permanently remove "${image.title}" from your library. This action cannot be undone.
+              </p>
+              <div class="dialog-actions">
+                <button class="button button-secondary" type="button" data-close-dialog>Cancel</button>
+                <button class="button button-danger" type="button" data-confirm-delete>Delete image</button>
+              </div>
+            </div>
+          </dialog>
+        `;
+      }
+
+      function App() {
+        return `
+          ${Header()}
+          <main class="app-shell" id="maincontent" tabindex="-1">
+            <p class="eyebrow">Preview</p>
+            <h1>Image preview</h1>
+            <p class="lead">
+              Review the selected image before making changes to your library.
+            </p>
+            <div class="preview-layout">
+              ${ImagePreviewCard()}
+              ${DetailsPanel()}
+            </div>
+          </main>
+          ${DeleteDialog()}
+        `;
+      }
+
+      function wireDeleteDialog() {
+        const dialog = document.getElementById("delete-dialog");
+        const trigger = document.querySelector(".trigger");
+        const cancelButton = dialog.querySelector("[data-close-dialog]");
+        const confirmButton = dialog.querySelector("[data-confirm-delete]");
+        const status = document.getElementById("delete-status");
+
+        trigger.addEventListener("click", () => {
+          dialog.showModal();
+          cancelButton.focus();
+        });
+
+        cancelButton.addEventListener("click", () => {
+          dialog.close("cancel");
+        });
+
+        confirmButton.addEventListener("click", () => {
+          dialog.close("delete");
+          status.textContent = `"${image.title}" has been deleted from your library.`;
+          trigger.disabled = true;
+          trigger.textContent = "Image deleted";
+        });
+      }
+
+      document.getElementById("root").innerHTML = App();
+      wireDeleteDialog();
+    </script>
+  </body>
+</html>
