<html lang="en">
  <head>
    <meta charset="utf-8">
    <meta name="viewport" content="width=device-width, initial-scale=1">
    <title>Image preview - Lumina Library</title>
    <style>
      :root {
        color-scheme: light;
        --bg: #f5f7fb;
        --surface: #ffffff;
        --surface-muted: #eef3ff;
        --text: #111827;
        --muted: #4b5563;
        --border: #d5dce8;
        --primary: #2563eb;
        --primary-strong: #1d4ed8;
        --danger: #b42318;
        --danger-strong: #8f1d14;
        --danger-soft: #fff1f0;
        --shadow: 0 24px 70px rgb(15 23 42 / 18%);
        --radius-lg: 28px;
        --radius-md: 18px;
        --radius-sm: 12px;
        font-family:
          Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont,
          "Segoe UI", sans-serif;
      }

      * {
        box-sizing: border-box;
      }

      body {
        min-height: 100vh;
        margin: 0;
        color: var(--text);
        background:
          radial-gradient(circle at 15% 10%, #dbeafe 0, transparent 30%),
          radial-gradient(circle at 85% 8%, #fee2e2 0, transparent 26%),
          linear-gradient(135deg, #f8fafc 0%, var(--bg) 100%);
      }

      button {
        font: inherit;
      }

      .skip-link {
        position: fixed;
        inset-block-start: 1rem;
        inset-inline-start: 1rem;
        z-index: 10;
        transform: translateY(-150%);
        border-radius: 999px;
        padding: 0.75rem 1rem;
        color: #ffffff;
        background: var(--text);
        text-decoration: none;
      }

      .skip-link:focus {
        transform: translateY(0);
      }

      .app-shell {
        width: min(1120px, calc(100% - 2rem));
        margin: 0 auto;
      }

      .site-header {
        display: flex;
        align-items: center;
        justify-content: space-between;
        gap: 1rem;
        padding: 1.25rem 0;
      }

      .brand {
        display: inline-flex;
        align-items: center;
        gap: 0.75rem;
        color: var(--text);
        font-weight: 800;
        letter-spacing: -0.02em;
        text-decoration: none;
      }

      .brand-mark {
        display: grid;
        width: 2.5rem;
        height: 2.5rem;
        place-items: center;
        border-radius: 0.9rem;
        color: #ffffff;
        background: linear-gradient(135deg, #2563eb, #7c3aed);
        box-shadow: 0 10px 30px rgb(37 99 235 / 28%);
      }

      .primary-nav ul {
        display: flex;
        align-items: center;
        gap: 0.5rem;
        padding: 0;
        margin: 0;
        list-style: none;
      }

      .primary-nav a {
        display: inline-flex;
        min-height: 44px;
        align-items: center;
        border-radius: 999px;
        padding: 0 1rem;
        color: var(--muted);
        font-weight: 650;
        text-decoration: none;
      }

      .primary-nav a[aria-current="page"] {
        color: var(--primary-strong);
        background: #e0e7ff;
      }

      main {
        padding: 2rem 0 4rem;
      }

      .preview-layout {
        display: grid;
        grid-template-columns: minmax(0, 1.25fr) minmax(18rem, 0.75fr);
        gap: clamp(1rem, 4vw, 2.5rem);
        align-items: start;
      }

      .image-card,
      .details-panel {
        border: 1px solid rgb(213 220 232 / 82%);
        border-radius: var(--radius-lg);
        background: rgb(255 255 255 / 86%);
        box-shadow: var(--shadow);
        backdrop-filter: blur(18px);
      }

      .image-card {
        overflow: hidden;
      }

      .preview-art {
        display: block;
        width: 100%;
        height: auto;
        background: #dbeafe;
      }

      .image-actions {
        display: flex;
        flex-wrap: wrap;
        align-items: center;
        justify-content: space-between;
        gap: 1rem;
        padding: 1rem;
      }

      .image-meta {
        min-width: min(100%, 18rem);
      }

      .eyebrow {
        margin: 0 0 0.25rem;
        color: var(--primary-strong);
        font-size: 0.78rem;
        font-weight: 800;
        letter-spacing: 0.12em;
        text-transform: uppercase;
      }

      h1,
      h2,
      p {
        margin-block-start: 0;
      }

      h1 {
        margin-block-end: 0.75rem;
        font-size: clamp(2.25rem, 6vw, 4.75rem);
        line-height: 0.95;
        letter-spacing: -0.07em;
      }

      h2 {
        margin-block-end: 0.75rem;
        font-size: clamp(1.5rem, 3vw, 2.15rem);
        line-height: 1.05;
        letter-spacing: -0.045em;
      }

      .lead,
      .muted {
        color: var(--muted);
        line-height: 1.65;
      }

      .lead {
        max-width: 62ch;
        margin-block-end: 1.75rem;
        font-size: 1.08rem;
      }

      .details-panel {
        padding: clamp(1.25rem, 4vw, 2rem);
      }

      .metadata-list {
        display: grid;
        gap: 0.85rem;
        margin: 1.5rem 0 0;
      }

      .metadata-row {
        display: flex;
        justify-content: space-between;
        gap: 1rem;
        border-block-end: 1px solid var(--border);
        padding-block-end: 0.85rem;
      }

      .metadata-row:last-child {
        border-block-end: 0;
        padding-block-end: 0;
      }

      .metadata-label {
        color: var(--muted);
      }

      .metadata-value {
        font-weight: 750;
        text-align: end;
      }

      .button {
        display: inline-flex;
        min-height: 44px;
        align-items: center;
        justify-content: center;
        gap: 0.5rem;
        border: 1px solid transparent;
        border-radius: 999px;
        padding: 0.75rem 1rem;
        font-weight: 800;
        text-decoration: none;
        cursor: pointer;
        transition:
          transform 160ms ease,
          box-shadow 160ms ease,
          background-color 160ms ease;
      }

      .button:hover {
        transform: translateY(-1px);
      }

      .button:active {
        transform: translateY(0);
      }

      .button-primary {
        color: #ffffff;
        background: var(--primary);
        box-shadow: 0 12px 24px rgb(37 99 235 / 22%);
      }

      .button-primary:hover {
        background: var(--primary-strong);
      }

      .button-secondary {
        color: var(--text);
        background: #ffffff;
        border-color: var(--border);
      }

      .button-danger {
        color: #ffffff;
        background: var(--danger);
        box-shadow: 0 12px 24px rgb(180 35 24 / 20%);
      }

      .button-danger:hover {
        background: var(--danger-strong);
      }

      .trigger {
        color: var(--danger);
        background: var(--danger-soft);
        border-color: #ffc9c5;
      }

      .trigger:hover {
        color: #ffffff;
        background: var(--danger);
      }

      :focus-visible {
        outline: 3px solid #111827;
        outline-offset: 3px;
      }

      .sr-only {
        position: absolute;
        width: 1px;
        height: 1px;
        padding: 0;
        margin: -1px;
        overflow: hidden;
        clip: rect(0, 0, 0, 0);
        white-space: nowrap;
        border: 0;
      }

      .status-message {
        margin: 1.25rem 0 0;
        color: var(--danger-strong);
        font-weight: 750;
      }

      dialog {
        width: min(92vw, 31rem);
        max-height: min(42rem, calc(100vh - 2rem));
        overflow: auto;
        border: 0;
        border-radius: 1.5rem;
        padding: 0;
        color: var(--text);
        background: var(--surface);
        box-shadow: 0 32px 90px rgb(15 23 42 / 30%);
      }

      dialog::backdrop {
        background: rgb(15 23 42 / 55%);
        backdrop-filter: blur(8px);
      }

      .dialog-content {
        padding: clamp(1.25rem, 5vw, 2rem);
      }

      .dialog-icon {
        display: grid;
        width: 3rem;
        height: 3rem;
        margin-block-end: 1rem;
        place-items: center;
        border-radius: 1rem;
        color: var(--danger);
        background: var(--danger-soft);
      }

      .dialog-actions {
        display: flex;
        flex-wrap: wrap;
        justify-content: flex-end;
        gap: 0.75rem;
        margin-block-start: 1.5rem;
      }

      @media (prefers-reduced-motion: reduce) {
        *,
        *::before,
        *::after {
          scroll-behavior: auto !important;
          transition-duration: 0.01ms !important;
          animation-duration: 0.01ms !important;
          animation-iteration-count: 1 !important;
        }
      }

      @media (max-width: 760px) {
        .site-header,
        .image-actions,
        .dialog-actions {
          align-items: stretch;
          flex-direction: column;
        }

        .primary-nav ul {
          flex-wrap: wrap;
        }

        .preview-layout {
          grid-template-columns: 1fr;
        }

        .button,
        .primary-nav a {
          width: 100%;
        }
      }

      @media (forced-colors: active) {
        .image-card,
        .details-panel,
        dialog,
        .button,
        .brand-mark,
        .dialog-icon {
          border: 1px solid CanvasText;
          box-shadow: none;
        }

        dialog::backdrop {
          background: Canvas;
        }
      }
    </style>
  </head>
